input.sparql:
SELECT ?work ?workLabel ?author ?authorLabel ?lcsh ?fast WHERE {
  ?work wdt:P31/wdt:P279* wd:Q732577 . # scholarly article or subclass
  ?work wdt:P921 ?subject .
  ?subject (wdt:P31|wdt:P106)* wd:Q5 . # subject is human or has occupation relating to human
  ?subject wdt:P27* wd:Q1747689 . # from Ancient Rome
  ?work wdt:P244 ?lcsh . # has LCSH identifier
  OPTIONAL { ?work wdt:P2163 ?fast } # FAST identifier
  OPTIONAL { ?work wdt:P50 ?author } # author
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?work ?workLabel ?subject ?subjectLabel WHERE {
  ?work wdt:P921 ?subject .
  ?subject wdt:P31 wd:Q5 . # human
  ?subject wdt:P27 wd:Q1747689 . # from Ancient Rome
  ?work wdt:P31 wd:Q13442814 . # scholarly article
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?work ?workLabel ?lcsh WHERE {
  ?work wdt:P921 wd:Q17167 . # main subject: Roman Republic
  ?work wdt:P244 ?lcsh . # has LCSH identifier
  ?work wdt:P31 ?type .
  FILTER(?type = wd:Q13442814 || ?type = wd:Q571 || ?type = wd:Q7725634) # article, book, or literary work
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?work ?workLabel ?subject ?subjectLabel WHERE {
  ?work wdt:P921 ?subject .
  ?subject wdt:P361* wd:Q17167 . # subject is part of Roman Republic
  ?work wdt:P31 wd:Q13442814 . # scholarly article
  FILTER(CONTAINS(LCASE(?workLabel), "biography") || CONTAINS(LCASE(?workLabel), "prosopography"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}
